result.text:
      const sup = supplierById(inv.supplierId);
      const hay = [inv.number, sup && sup.name, sup && sup.nif, inv.issueDate, String(inv.total)]
        .filter(Boolean)
        .join(" ")
        .toLowerCase();
      return hay.includes(needle);
    });
  }
  return sortedInvoices(list);
}

